// Nova Limits: Tageslimit gesamt + Limit pro Sitzung + maximale Nachrichtenlänge
// Zahlen hier ändern, dann speichern.
const MAX_PER_DAY = 100;    // Nachrichten pro Tag insgesamt (harte Kostenbremse)
const MAX_PER_SESSION = 12; // Nachrichten pro Gespräch
const MAX_CHARS = 500;      // Zeichen pro Nachricht
const MAIL = 'seitenklar.kontakt@gmail.com';

const item = $input.first().json;
const text = String(item.chatInput ?? '');
const sid = 's_' + String(item.sessionId ?? 'unknown');
const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Vienna' });

// Zähler liegen in den Workflow-Daten (bleiben nach Neustart erhalten, nur im aktiven Workflow)
const data = $getWorkflowStaticData('global');
if (data.day !== today) { data.day = today; data.total = 0; data.sessions = {}; }

const block = (msg) => [{ json: { ...item, blocked: true, output: msg } }];

if (text.length > MAX_CHARS) {
  return block(`Bitte fassen Sie sich kürzer (maximal ${MAX_CHARS} Zeichen).`);
}
if (data.total >= MAX_PER_DAY) {
  return block(`Das Tageslimit für den Chat ist erreicht. Bitte schreiben Sie uns eine E-Mail an ${MAIL}.`);
}
const used = data.sessions[sid] || 0;
if (used >= MAX_PER_SESSION) {
  return block(`Das Nachrichtenlimit für dieses Gespräch ist erreicht. Bitte schreiben Sie uns eine E-Mail an ${MAIL}.`);
}

data.total += 1;
data.sessions[sid] = used + 1;
return [{ json: { ...item, blocked: false } }];
